view.renderAuthorClassificationModal:
function renderAuthorClassificationModal(opts) {
  opts = opts || {};
  var authors = opts.authors || [];
  var unknown = opts.unknown || [];
  var assumed = opts.assumed || [];
  var isStandalone = !!opts.standalone;
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Build the overlay manually (not via showEliDialog) because the v2
  // shape includes per-row interactive controls + a header that doesn't
  // fit the dialog primitive's flat body+buttons layout.
  var existing = document.getElementById("_eli3_authors_overlay");
  if (existing) existing.remove();
  var overlay = document.createElement("div");
  overlay.id = "_eli3_authors_overlay";
  overlay.className = "eli-overlay _eli3_authors_overlay";
  var modal = document.createElement("div");
  modal.className = "_eli3_authors_modal";

  function _row(name) {
    var resolved = opts.currentKind(name);
    var saved = opts.isSaved(name);
    var idx = authors.indexOf(name);
    var badgeClass = saved ? "_eli3_authors_badge_saved" : "_eli3_authors_badge_auto";
    var badgeLabel = saved ? "SAVED" : "AUTO";
    function _btnClass(kind) {
      return "_eli3_authors_btn" + (resolved === kind ? " _eli3_authors_btn_" + kind + "_on" : "");
    }
    return '<div class="_eli3_authors_row" data-author-idx="' + idx + '" data-author="' + _esc(name) +
        '" data-resolved="' + _esc(resolved || "") + '">' +
      '<div class="_eli3_authors_row_head">' +
        '<div class="_eli3_authors_row_name">' + _esc(name) + '</div>' +
        (resolved
          ? '<div class="_eli3_authors_badge ' + badgeClass + '">' + badgeLabel + '</div>'
          : '<div class="_eli3_authors_badge _eli3_authors_badge_need">NEEDS CLASSIFICATION</div>') +
      '</div>' +
      '<div class="_eli3_authors_choice">' +
        '<button type="button" data-kind="internal" class="' + _btnClass("internal") + '">👤 Colgate</button>' +
        '<button type="button" data-kind="external" class="' + _btnClass("external") + '">🏢 Third Party</button>' +
        '<button type="button" data-kind="unknown" class="' + _btnClass("unknown") + '" title="Unknown">?</button>' +
      '</div>' +
    '</div>';
  }

  var assumedHtml = assumed.length
    ? '<details class="_eli3_authors_assumed_wrap" ' + (unknown.length ? "" : "open") + '>' +
        '<summary class="_eli3_authors_assumed_sum">' +
          '<span class="_eli3_authors_chev">▾</span>' +
          assumed.length + ' Classified Author' + (assumed.length === 1 ? "" : "s") +
        '</summary>' +
        '<div class="_eli3_authors_list">' + assumed.map(_row).join("") + '</div>' +
      '</details>'
    : "";

  var unknownHtml = unknown.length
    ? '<div class="_eli3_authors_unknown_head">' +
        '<span>⚠️</span> NEEDS CLASSIFICATION' +
      '</div>' +
      '<div class="_eli3_authors_list">' + unknown.map(_row).join("") + '</div>'
    : "";

  modal.innerHTML =
    '<button type="button" class="_eli3_authors_close" aria-label="Close">&times;</button>' +
    '<div class="_eli3_authors_eyebrow">REDLINES DETECTED — AUTHOR ATTRIBUTION</div>' +
    '<div class="_eli3_authors_title">Who do these authors work for?</div>' +
    '<div class="_eli3_authors_desc">' +
      'I found ' + authors.length + ' author' + (authors.length === 1 ? "" : "s") +
      ' in ' + _esc(opts.sourceLabel || "this document") +
      '. Classify them below to help ELI provide better, tailored analysis.' +
    '</div>' +
    unknownHtml +
    assumedHtml +
    '<div class="_eli3_authors_footer">' +
      '<button type="button" class="_eli3_authors_reset">Reset identifications</button>' +
      '<button type="button" class="_eli3_authors_continue">' +
        (isStandalone ? "Save" : "Continue") +
      '</button>' +
    '</div>';

  overlay.appendChild(modal);
  document.body.appendChild(overlay);

  function _close() { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); }

  modal.querySelector("._eli3_authors_close").onclick = function () {
    _close();
    if (typeof opts.onCancel === "function") opts.onCancel();
  };

  // Per-row classification buttons. Update DOM state + notify caller.
  modal.querySelectorAll("._eli3_authors_choice").forEach(function (choice) {
    choice.addEventListener("click", function (ev) {
      var btn = ev.target.closest("button[data-kind]");
      if (!btn) return;
      var row = btn.closest("[data-author]");
      if (!row) return;
      var name = row.getAttribute("data-author");
      var kind = btn.getAttribute("data-kind");
      row.setAttribute("data-resolved", kind);
      // Repaint the three buttons in this row.
      choice.querySelectorAll("button[data-kind]").forEach(function (b) {
        var k = b.getAttribute("data-kind");
        b.className = "_eli3_authors_btn" + (k === kind ? " _eli3_authors_btn_" + k + "_on" : "");
      });
      // Swap AUTO badge → EDITED.
      var autoBadge = row.querySelector("._eli3_authors_badge_auto");
      if (autoBadge) {
        autoBadge.className = "_eli3_authors_badge _eli3_authors_badge_edited";
        autoBadge.textContent = "EDITED";
      }
      var needBadge = row.querySelector("._eli3_authors_badge_need");
      if (needBadge) {
        needBadge.className = "_eli3_authors_badge _eli3_authors_badge_edited";
        needBadge.textContent = "EDITED";
      }
      if (typeof opts.onChoice === "function") opts.onChoice(name, kind);
    });
  });

  // Reset: two-click confirm (matches v2 pattern).
  var resetBtn = modal.querySelector("._eli3_authors_reset");
  resetBtn.onclick = function () {
    if (resetBtn.getAttribute("data-confirming") !== "1") {
      resetBtn.setAttribute("data-confirming", "1");
      resetBtn.textContent = "Click again to confirm reset";
      resetBtn.classList.add("_eli3_authors_reset_confirm");
      setTimeout(function () {
        if (resetBtn.getAttribute("data-confirming") === "1") {
          resetBtn.removeAttribute("data-confirming");
          resetBtn.textContent = "Reset identifications";
          resetBtn.classList.remove("_eli3_authors_reset_confirm");
        }
      }, 3500);
      return;
    }
    resetBtn.removeAttribute("data-confirming");
    Promise.resolve(typeof opts.onReset === "function" ? opts.onReset() : null)
      .then(function () { _close(); });
  };

  modal.querySelector("._eli3_authors_continue").onclick = function () {
    Promise.resolve(typeof opts.onContinue === "function" ? opts.onContinue() : null)
      .then(function () { _close(); });
  };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["redline_authors"];
  var vfns = bundle && bundle._eliViewFns || {};
  var renderModal = vfns.renderAuthorClassificationModal;
  if (!renderModal) {
    eli.log.event("tool", "redline_authors_load_failed", {});
    return;
  }

  // ─── Pure helpers (formerly engine.js; moved into the init closure so
  // they can call each other — the bundler evals each engine top-level
  // function in its own new Function() with no shared scope, which
  // breaks cross-references like classifyAuthors → rosterLookup) ──
  function parseLastFirstInitial(name) {
    if (!name) return null;
    var s = String(name).trim().replace(/<[^>]+>/g, "").trim();
    if (!s) return null;
    if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s)) {
      s = s.split("@")[0].replace(/[._\-]+/g, " ").trim();
    }
    var first, last;
    if (s.indexOf(",") !== -1) {
      var commaParts = s.split(",");
      last = (commaParts[0] || "").trim();
      first = (commaParts[1] || "").trim().split(/\s+/)[0] || "";
    } else {
      var parts = s.split(/\s+/).filter(function (p) { return p.length > 0; });
      if (parts.length < 2) return null;
      first = parts[0];
      last = parts[parts.length - 1];
    }
    if (!first || !last) return null;
    return { firstInitial: first.charAt(0).toLowerCase(), lastName: last.toLowerCase() };
  }
  function rosterLookup(roster, name) {
    if (!roster || !name) return null;
    if (roster[name]) return roster[name];
    var lower = String(name).trim().toLowerCase();
    var keys = Object.keys(roster);
    for (var i = 0; i < keys.length; i++) {
      if (keys[i].trim().toLowerCase() === lower) return roster[keys[i]];
    }
    return null;
  }
  function isKnownInternalAgainst(authorName, userFullName, internalNamesLower) {
    if (!authorName) return false;
    if (Array.isArray(internalNamesLower) && internalNamesLower.length) {
      var lc = String(authorName).trim().toLowerCase();
      for (var i = 0; i < internalNamesLower.length; i++) {
        if (lc === internalNamesLower[i]) return true;
      }
    }
    if (!userFullName) return false;
    var userParsed = parseLastFirstInitial(userFullName);
    if (!userParsed) return false;
    var authorParsed = parseLastFirstInitial(authorName);
    if (!authorParsed) return false;
    return authorParsed.lastName === userParsed.lastName &&
           authorParsed.firstInitial === userParsed.firstInitial;
  }
  function classifyAuthors(authors, roster, userFullName, internalNamesLower) {
    if (!authors || !authors.length) return {};
    var out = {};
    authors.forEach(function (a) {
      var saved = rosterLookup(roster, a);
      if (saved) { out[a] = saved; return; }
      if (isKnownInternalAgainst(a, userFullName, internalNamesLower)) {
        out[a] = "internal";
        return;
      }
      out[a] = "external";
    });
    return out;
  }
  function getUnclassifiedAuthors(authors, roster, userFullName, internalNamesLower) {
    if (!authors || !authors.length) return [];
    return authors.filter(function (a) {
      if (!a) return false;
      if (rosterLookup(roster, a)) return false;
      if (isKnownInternalAgainst(a, userFullName, internalNamesLower)) return false;
      return true;
    });
  }

  var ROSTER_KEY = "eli_author_roster";
  var _rosterCache = null;
  var _internalNamesCache = null; // { names: [lower], emails: [lower] }

  function _userFullName() {
    try {
      var raw = eli.compat && eli.compat.lsGet("eli_user_settings");
      if (raw) {
        var s = JSON.parse(raw);
        return String((s && (s.name || s.userName || s.displayName)) || "");
      }
    } catch (e) {}
    try {
      return String(
        (eli.compat && (eli.compat.lsGet("eli_user_name") || eli.compat.lsGet("userName"))) || ""
      );
    } catch (e) {}
    return "";
  }
  function _internalNamesLower() {
    if (!_internalNamesCache) return [];
    return (_internalNamesCache.names || []).concat(_internalNamesCache.emails || []);
  }

  function _readRosterFromDoc() {
    try {
      if (typeof Office === "undefined" || !Office.context || !Office.context.document ||
          !Office.context.document.settings) return {};
      var raw = Office.context.document.settings.get(ROSTER_KEY);
      if (!raw) return {};
      var parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
      return parsed && typeof parsed === "object" ? parsed : {};
    } catch (e) { return {}; }
  }
  function _writeRosterToDoc(roster) {
    return new Promise(function (resolve) {
      try {
        if (typeof Office === "undefined" || !Office.context || !Office.context.document ||
            !Office.context.document.settings) return resolve();
        Office.context.document.settings.set(ROSTER_KEY, JSON.stringify(roster || {}));
        Office.context.document.settings.saveAsync(function () { resolve(); });
      } catch (e) { resolve(); }
    });
  }
  function ensureRosterLoaded() {
    var fromDoc = _readRosterFromDoc();
    var mem = _rosterCache && typeof _rosterCache === "object" ? _rosterCache : {};
    _rosterCache = Object.assign({}, fromDoc, mem);
    return Promise.resolve(_rosterCache);
  }
  function getRoster() {
    if (!_rosterCache) _rosterCache = _readRosterFromDoc();
    return _rosterCache || {};
  }
  function setClassification(name, kind) {
    if (!name) return;
    var r = _rosterCache || _readRosterFromDoc();
    if (!kind) {
      delete r[name];
    } else if (kind === "internal" || kind === "external" || kind === "unknown") {
      r[name] = kind;
    } else {
      delete r[name];
    }
    _rosterCache = r;
  }
  function clearRoster() {
    _rosterCache = {};
    return _writeRosterToDoc({});
  }

  function ensureInternalNamesLoaded() {
    if (_internalNamesCache) return Promise.resolve(_internalNamesCache);
    if (!eli.storage || typeof eli.storage.getAll !== "function") {
      _internalNamesCache = { names: [], emails: [] };
      return Promise.resolve(_internalNamesCache);
    }
    return eli.storage.getAll("requesters").then(function (rows) {
      var names = [], emails = [];
      (rows || []).forEach(function (r) {
        if (r && r.name) names.push(String(r.name).trim().toLowerCase());
        if (r && r.email) emails.push(String(r.email).trim().toLowerCase());
      });
      _internalNamesCache = { names: names, emails: emails };
      return _internalNamesCache;
    }).catch(function () {
      _internalNamesCache = { names: [], emails: [] };
      return _internalNamesCache;
    });
  }

  // === Public API ===
  // classify(authors) → {author: kind}
  function classify(authors) {
    return classifyAuthors(authors || [], getRoster(), _userFullName(), _internalNamesLower());
  }
  // unclassified(authors) → [string]
  function unclassified(authors) {
    return getUnclassifiedAuthors(authors || [], getRoster(), _userFullName(), _internalNamesLower());
  }
  // isKnownInternal(author) → bool — used by review_redlines'
  // promptTrackPortAuthorsDialog auto-classify shortcut.
  function isKnownInternal(name) {
    return isKnownInternalAgainst(name, _userFullName(), _internalNamesLower());
  }

  // openModal({authors, source, standalone}) → Promise<classification>
  // Opens the modal so the user can re-classify any author. Resolves
  // with the new classification map. Reset wipes the doc-saved roster
  // and resolves with {}.
  function openModal(args) {
    args = args || {};
    var authors = args.authors || [];
    return Promise.all([ensureRosterLoaded(), ensureInternalNamesLoaded()]).then(function () {
      return new Promise(function (resolve) {
        var unknown = unclassified(authors);
        var assumed = authors.filter(function (a) { return a && unknown.indexOf(a) === -1; });
        // If no authors at all, just resolve to empty classification.
        if (!authors.length) { resolve({}); return; }
        renderModal({
          authors: authors,
          unknown: unknown,
          assumed: assumed,
          sourceLabel: args.source || "this document",
          standalone: args.standalone !== false,
          currentKind: function (name) {
            var saved = rosterLookup(getRoster(), name);
            if (saved) return saved;
            return isKnownInternal(name) ? "internal" : "external";
          },
          isSaved: function (name) { return !!rosterLookup(getRoster(), name); },
          onChoice: function (name, kind) { setClassification(name, kind); },
          onContinue: function () {
            return _writeRosterToDoc(getRoster()).then(function () {
              resolve(classify(authors));
            });
          },
          onReset: function () {
            return clearRoster().then(function () {
              resolve({});
            });
          },
          onCancel: function () { resolve(classify(authors)); },
        });
      });
    });
  }

  // openModalForDocRedlines() — sidebar entry point: pulls authors from
  // the active document's tracked changes, then opens the modal.
  function openModalForDocRedlines() {
    if (typeof Word === "undefined" || !Word.run) {
      if (typeof showToast === "function") showToast("Word host not available.", "err");
      return Promise.resolve({});
    }
    return Word.run(function (context) {
      var changes = context.document.body.getTrackedChanges();
      changes.load("items/author");
      return context.sync().then(function () {
        var seen = {};
        for (var i = 0; i < changes.items.length; i++) {
          var a = changes.items[i].author;
          if (a) seen[a] = true;
        }
        return Object.keys(seen);
      });
    }).then(function (authors) {
      if (!authors.length) {
        if (typeof showToast === "function") showToast("No tracked changes in this document.", "info");
        return {};
      }
      return openModal({ authors: authors, standalone: true });
    }).catch(function (err) {
      if (typeof showToast === "function") showToast("Couldn't read tracked changes: " + (err && err.message || "unknown"), "err");
      return {};
    });
  }

  // === Register dispatch channel (v3-clean) ===
  eli.register({
    authors: {
      open:            openModalForDocRedlines,
      openWith:        openModal,
      classify:        classify,
      unclassified:    unclassified,
      roster:          getRoster,
      setClassification: setClassification,
      isKnownInternal: isKnownInternal,
      ensureLoaded:    ensureRosterLoaded,
      reset:           clearRoster,
    },
  });

  // === v2-compat window globals (so ported v2 IIFE code keeps working) ===
  window.getAuthorRoster              = getRoster;
  window.setAuthorClassification      = setClassification;
  window.classifyAuthorsForPrompt     = classify;
  window.getUnclassifiedAuthors       = unclassified;
  window._openRedlineAuthorModal      = openModalForDocRedlines;
  window._eliIsKnownInternal          = isKnownInternal;
  window._eliEnsureAuthorRosterLoaded = ensureRosterLoaded;
  window._eliEnsureInternalNamesLoaded = ensureInternalNamesLoaded;
  window._eliShowAuthorClassificationModal = function (authors, options) {
    return openModal({
      authors: authors,
      source: options && options.source,
      standalone: !!(options && options.standalone),
    });
  };

  // Pre-warm caches so the first sidebar click is instant.
  ensureRosterLoaded();
  ensureInternalNamesLoaded();

  eli.log.event("tool", "redline_authors_initialized", {});
}

jsonTools.css:
/* tools/redline_authors/style.css — author classification modal.
 * Visual cues match the v2 modal but ported off inline-style soup. */

._eli3_authors_overlay {
  background: rgba(15, 23, 42, 0.45);
}
._eli3_authors_modal {
  position: relative;
  background: #fff;
  width: 460px;
  max-width: 92vw;
  max-height: 88vh;
  overflow-y: auto;
  padding: 28px;
  padding-top: 40px;
  border: 1px solid #cbd5e1;
  border-left: 4px solid var(--color-gold, #c9a227);
  box-shadow: 0 16px 48px rgba(15, 23, 42, 0.28);
  box-sizing: border-box;
}
._eli3_authors_close {
  position: absolute;
  top: 8px; right: 10px;
  width: 30px; height: 30px;
  padding: 0;
  border: none;
  background: transparent;
  color: #64748b;
  font: 600 18px/1 'Inter', sans-serif;
  cursor: pointer;
  border-radius: 4px;
}
._eli3_authors_close:hover { background: #f1f5f9; color: #0f172a; }
._eli3_authors_eyebrow {
  font: 800 10px/1 'Inter', sans-serif;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: #a07d12;
  margin-bottom: 8px;
}
._eli3_authors_title {
  font: 700 18px/1.25 'Georgia', serif;
  color: #0f172a;
  margin-bottom: 10px;
}
._eli3_authors_desc {
  font: 400 13px/1.55 'Inter', sans-serif;
  color: #475569;
  margin-bottom: 18px;
}
._eli3_authors_unknown_head {
  display: flex;
  align-items: center;
  gap: 6px;
  font: 800 10px/1 'Inter', sans-serif;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: #dc2626;
  margin: 4px 0 10px;
}
._eli3_authors_list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 14px;
}
._eli3_authors_row {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
._eli3_authors_row_head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
._eli3_authors_row_name {
  font: 700 13px/1.2 'Inter', sans-serif;
  color: #0f172a;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
._eli3_authors_badge {
  font: 700 9px/1 'Inter', sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  padding: 3px 6px;
  flex-shrink: 0;
}
._eli3_authors_badge_saved { background: #f1f5f9; color: #475569; border: 1px solid #cbd5e1; }
._eli3_authors_badge_auto  { background: #dcfce7; color: #16a34a; }
._eli3_authors_badge_edited { background: #fef3c7; color: #92400e; }
._eli3_authors_badge_need { background: #fee2e2; color: #b91c1c; }
._eli3_authors_choice {
  display: flex;
  gap: 6px;
}
._eli3_authors_btn {
  flex: 1;
  padding: 8px 10px;
  font: 600 12px/1 'Inter', sans-serif;
  cursor: pointer;
  background: #f8fafc;
  color: #475569;
  border: 1px solid #cbd5e1;
}
._eli3_authors_btn:last-child {
  flex: 0 0 36px;
  font-weight: 700;
}
._eli3_authors_btn_internal_on { background: #1565c0; color: #fff; border-color: #1565c0; }
._eli3_authors_btn_external_on { background: #475569; color: #fff; border-color: #475569; }
._eli3_authors_btn_unknown_on  { background: #d97706; color: #fff; border-color: #d97706; }
._eli3_authors_assumed_wrap {
  border-top: 1px solid #e2e8f0;
  padding-top: 12px;
  margin-bottom: 14px;
}
._eli3_authors_assumed_sum {
  font: 800 10px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #64748b;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  outline: none;
  user-select: none;
  list-style: none;
  margin-bottom: 8px;
}
._eli3_authors_assumed_sum::-webkit-details-marker { display: none; }
._eli3_authors_assumed_wrap[open] ._eli3_authors_chev { transform: rotate(0deg); }
._eli3_authors_chev {
  display: inline-block;
  transform: rotate(-90deg);
  transition: transform 0.15s;
}
._eli3_authors_assumed_wrap[open] ._eli3_authors_chev { transform: none; }
._eli3_authors_footer {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 12px;
}
._eli3_authors_reset {
  background: transparent;
  border: none;
  color: #dc2626;
  font: 600 11px/1 'Inter', sans-serif;
  cursor: pointer;
  text-decoration: underline;
  margin-right: auto;
}
._eli3_authors_reset_confirm { color: #dc2626; font-weight: 800; }
._eli3_authors_continue {
  background: var(--color-blue, #1565c0);
  color: #fff;
  border: none;
  padding: 9px 20px;
  font: 700 12px/1 'Inter', sans-serif;
  cursor: pointer;
}
._eli3_authors_continue:hover { background: #0d47a1; }
